import java.io.*;import java.util.*;public class Main{public static void main(String[] args) throws IOException{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));StringBuilder sb=new StringBuilder();int T=Integer.parseInt(br.readLine().trim());for(int t=0;t<T;t++){String line;while((line=br.readLine())!=null&&line.trim().isEmpty()){}int N=Integer.parseInt(line.trim());double base=0.143*N;double val=Math.pow(base,N);long ans=Math.round(val);sb.append(ans);if(t<T-1)sb.append('\n');}System.out.print(sb.toString());}}